def main():
    if len(sys.argv) != 2: print('usage: python3 E_patch.py <file.html>'); sys.exit(2)
    p = sys.argv[1]; src = open(p, encoding='utf-8').read()
    for name, old, new in EDITS:
        n = src.count(old)
        assert n == 1, '%s: anchor found %d times' % (name, n)
    for name, old, new in EDITS:
        src = src.replace(old, new, 1); print('applied', name)
    open(p, 'w', encoding='utf-8').write(src)
    print('E_patch: %d edits applied to %s' % (len(EDITS), p))
if __name__ == '__main__': main()
